// tests/test_fishhash.cpp
//
// Oracle gate for the CPU FishHash port (U2). Verifies src/fishhash.cpp
// byte-exactly against tests/vectors/vectors.json, which was generated by
// tools/vecgen.cpp and cross-checked against the `fish_hash` crate v0.3.0
// (the network's verifier) and the node's published vector.
//
// Usage: test_fishhash <vectors.json>

#include <chrono>
#include <cctype>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

#include "fishhash.h"
#include "json.h"
#include "blake3.h"
#include "keccak.h"

using fishhash::Json;
using fishhash::JsonParser;

namespace {

int g_checks = 0;
int g_failures = 0;

#define CHECK(cond, msg)                                                     \
  do {                                                                       \
    ++g_checks;                                                              \
    if (!(cond)) {                                                           \
      ++g_failures;                                                          \
      std::printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, msg);              \
    }                                                                        \
  } while (0)

// (JSON value + parser moved to src/json.h, shared with the miner)

// ── Hex helpers ───────────────────────────────────────────────────────────
int hexVal(char c) {
  if (c >= '0' && c <= '9') return c - '0';
  if (c >= 'a' && c <= 'f') return c - 'a' + 10;
  if (c >= 'A' && c <= 'F') return c - 'A' + 10;
  return -1;
}

bool unhex(const std::string& s, std::vector<uint8_t>& out) {
  if (s.size() % 2) return false;
  out.resize(s.size() / 2);
  for (size_t i = 0; i < out.size(); ++i) {
    int hi = hexVal(s[2 * i]), lo = hexVal(s[2 * i + 1]);
    if (hi < 0 || lo < 0) return false;
    out[i] = (uint8_t)((hi << 4) | lo);
  }
  return true;
}

template <size_t N>
bool bytesEqual(const std::vector<uint8_t>& bytes, const uint8_t (&arr)[N]) {
  return bytes.size() == N && std::memcmp(bytes.data(), arr, N) == 0;
}

bool bytesEqual(const std::vector<uint8_t>& a, const uint8_t* b, size_t n) {
  return a.size() == n && std::memcmp(a.data(), b, n) == 0;
}

// ── Test stages ───────────────────────────────────────────────────────────
void checkSeedConstant(const Json& root, const std::vector<fishhash::Hash512>& chain) {
  // The hardcoded dataset seed must equal BLAKE3-256("FishHash"), and the
  // chain's first item must be keccak512(seed).
  const std::string& seedInput = root.at("constants").at("seed_input").str;
  blake3_hasher h;
  blake3_hasher_init(&h);
  blake3_hasher_update(&h, seedInput.data(), seedInput.size());
  uint8_t seed[32];
  blake3_hasher_finalize(&h, seed, 32);
  fishhash::Hash512 expected;
  keccak(expected.word64s, 512, seed, 32);
  CHECK(bytesEqual(std::vector<uint8_t>(expected.bytes, expected.bytes + 64),
                   chain[0].bytes, 64),
        "seed = BLAKE3-256(\"FishHash\"), chain[0] = keccak512(seed)");
}

void checkLightCache(const Json& root, fishhash::LightCache& lc) {
  const auto& pre = root.at("light_cache").at("pre_rounds").obj;
  const auto& post = root.at("light_cache").at("post_rounds").obj;
  CHECK(pre.size() > 0 && post.size() > 0, "light cache samples present");

  // Pre-round items: rebuild the chain and compare samples.
  auto chain = fishhash::buildLightCacheChain();
  checkSeedConstant(root, chain);
  for (const auto& [idx, j] : pre) {
    std::vector<uint8_t> expected;
    CHECK(unhex(j.str, expected), "pre_rounds hex");
    std::string msg = "pre_rounds[" + idx + "]";
    CHECK(bytesEqual(expected, chain[std::stoul(idx)].bytes, 64), msg.c_str());
  }
  for (const auto& [idx, j] : post) {
    std::vector<uint8_t> expected;
    CHECK(unhex(j.str, expected), "post_rounds hex");
    std::string msg = "post_rounds[" + idx + "]";
    CHECK(bytesEqual(expected, lc.item(std::stoul(idx)).bytes, 64),
          msg.c_str());
  }
}

void checkDatasetItems(const Json& root, const fishhash::LightCache& lc) {
  const auto& items = root.at("dataset_items").obj;
  CHECK(items.size() > 0, "dataset item samples present");
  for (const auto& [idx, j] : items) {
    std::vector<uint8_t> expected;
    CHECK(unhex(j.str, expected), "dataset item hex");
    fishhash::Hash1024 actual = fishhash::datasetItem(lc, std::stoul(idx));
    std::string msg = "datasetItem[" + idx + "]";
    CHECK(bytesEqual(expected, actual.bytes, 128), msg.c_str());
  }
}

void checkVectors(const Json& root, const fishhash::LightCache& lc) {
  const auto& vectors = root.at("vectors").arr;
  CHECK(vectors.size() == 8, "8 vectors");
  fishhash::ComputedItemSource src(lc);

  for (size_t vi = 0; vi < vectors.size(); ++vi) {
    const Json& v = vectors[vi];
    std::string name = "vector[" + std::to_string(vi) + "]";
    std::vector<uint8_t> header;
    CHECK(unhex(v.at("header").str, header), (name + " header").c_str());

    auto t0 = std::chrono::steady_clock::now();
    auto trace = fishhash::fishHashTrace(src, header.data(), header.size());
    auto hash = fishhash::fishHash(src, header.data(), header.size());
    auto t1 = std::chrono::steady_clock::now();
    double ms =
        std::chrono::duration_cast<std::chrono::microseconds>(t1 - t0).count() /
        1000.0;

    std::vector<uint8_t> startExpected;
    CHECK(unhex(v.at("start_value").str, startExpected),
          (name + " start_value").c_str());
    CHECK(bytesEqual(startExpected, trace.startValue.bytes, 64),
          (name + " start_value bytes").c_str());

    const auto& rounds = v.at("rounds").arr;
    CHECK(rounds.size() == fishhash::kDatasetAccesses, (name + " rounds").c_str());
    for (size_t r = 0; r < rounds.size(); ++r) {
      const Json& rd = rounds[r];
      CHECK(rd.arr.size() == 4, (name + " round arity").c_str());
      uint32_t p[3] = {
          (uint32_t)rd.arr[0].num, (uint32_t)rd.arr[1].num,
          (uint32_t)rd.arr[2].num};
      for (int k = 0; k < 3; ++k)
        CHECK(trace.p[r][k] == p[k], (name + " p[" + std::to_string(r) + "]")
                                         .c_str());
      std::vector<uint8_t> mixExpected;
      CHECK(unhex(rd.arr[3].str, mixExpected), (name + " mix hex").c_str());
      CHECK(bytesEqual(mixExpected, trace.mix[r].bytes, 128),
            (name + " mix[" + std::to_string(r) + "]").c_str());
    }

    std::vector<uint8_t> collapsedExpected;
    CHECK(unhex(v.at("collapsed").str, collapsedExpected),
          (name + " collapsed").c_str());
    CHECK(bytesEqual(collapsedExpected, trace.collapsed.bytes, 32),
          (name + " collapsed bytes").c_str());

    std::vector<uint8_t> hashExpected;
    CHECK(unhex(v.at("expected").str, hashExpected), (name + " expected").c_str());
    CHECK(bytesEqual(hashExpected, hash.bytes, 32),
          (name + " final hash").c_str());

    std::printf("  %s: OK (%.1f ms per hash, on-demand items)\n",
                name.c_str(), ms / 2);
  }
}

void checkConstants(const Json& root) {
  const auto& c = root.at("constants");
  CHECK(c.at("fnv_prime").num == fishhash::kFnvPrime, "fnv_prime");
  CHECK(c.at("full_dataset_item_parents").num ==
            fishhash::kDatasetItemParents,
        "item parents");
  CHECK(c.at("num_dataset_accesses").num == fishhash::kDatasetAccesses,
        "dataset accesses");
  CHECK(c.at("light_cache_rounds").num == fishhash::kLightCacheRounds,
        "light cache rounds");
  CHECK(c.at("light_cache_num_items").num == fishhash::kLightCacheItems,
        "light cache size");
  CHECK(c.at("full_dataset_num_items").num == fishhash::kDatasetItems,
        "dataset size");
}

}  // namespace

int main(int argc, char** argv) {
  if (argc < 2) {
    std::printf("usage: %s <vectors.json>\n", argv[0]);
    return 2;
  }
  std::ifstream f(argv[1]);
  if (!f) {
    std::printf("cannot open %s\n", argv[1]);
    return 2;
  }
  std::stringstream ss;
  ss << f.rdbuf();
  JsonParser parser(ss.str());
  Json root = parser.parseValue();

  std::printf("FishHash CPU port oracle gate\n");
  checkConstants(root);

  std::printf("building light cache (%u items)...\n", fishhash::kLightCacheItems);
  auto t0 = std::chrono::steady_clock::now();
  fishhash::LightCache lc;
  auto t1 = std::chrono::steady_clock::now();
  std::printf("  light cache: %.2f s\n",
              std::chrono::duration<double>(t1 - t0).count());

  checkLightCache(root, lc);
  checkDatasetItems(root, lc);
  std::printf("checking 8 full vectors...\n");
  checkVectors(root, lc);

  std::printf("%d checks, %d failures\n", g_checks, g_failures);
  if (g_failures) {
    std::printf("FAIL\n");
    return 1;
  }
  std::printf("PASS\n");
  return 0;
}
